/**
 * Checklist (vendor pipeline) domain schema.
 * IMPORTANT: Never store real vendor names, phone numbers, ratings, or
 * prices as facts. quoteMinorUnits is user-entered, not AI-generated.
 */
import { z } from 'zod';
import { MAX_NOTES_LENGTH, MAX_CHECKLIST_QUESTIONS, VENDOR_STATUSES } from '@/lib/constants';

export const VendorStatusSchema = z.enum(VENDOR_STATUSES);

export const ChecklistItemSchema = z.object({
  id: z.string(),
  vendorType: z.string().max(60),
  category: z.string().max(60),
  status: VendorStatusSchema,
  /** Questions generated by AI — vendor type guidance, not real recommendations. */
  questionsToAsk: z.array(z.string().max(200)).max(MAX_CHECKLIST_QUESTIONS),
  /** User-entered quote — feeds into actual budget tracker. */
  quoteMinorUnits: z.number().int().min(0).nullable(),
  notes: z.string().max(MAX_NOTES_LENGTH),
  contactedAt: z.string().datetime().nullable(),
  bookedAt: z.string().datetime().nullable(),
});

export const ChecklistSchema = z.object({
  items: z.array(ChecklistItemSchema).max(100),
});

export type ChecklistItem = z.infer<typeof ChecklistItemSchema>;
export type VendorStatus = z.infer<typeof VendorStatusSchema>;
export type Checklist = z.infer<typeof ChecklistSchema>;

